def post(origin):
    req = Request(base + "/api/v1/settings/privacy", method="PUT", data=b'{"crash_reports":false}',
                  headers={"Content-Type": "application/json", "Origin": origin})
    try:
        with urlopen(req, timeout=10) as r:
            return r.status
    except HTTPError as e:
        return e.code
